class Solution {
    public int singleNumber(int[] nums) {
        if (nums == null || nums.length % 2 == 0) {
            return -1;
        }

        var result = 0;
        for (var i = 0; i < nums.length; i++) {
            result ^= nums[i];
        }

        return result;
    }
}

